        <p className="mt-3 text-base sm:text-lg text-neutral-600 dark:text-neutral-400 max-w-xl">
          Recognitions, competitive hackathons, and accredited industry benchmarks.
        </p>
      </div>

      {/* Minimal Typography Rows / Cards */}
